mapper.select:
SELECT id, title, author, dynasty, genre, theme, difficulty, hot, len, quote, translation, analysis, tags, cover_url, audio_url, audio_duration, audio_type, season, emotion, scenery, festival, historical_period, poetic_form, rhetorical_device, famous_line_type
FROM poem
WHERE 1 = 1

    AND (
    title LIKE CONCAT('%', #{q}, '%')
    OR author LIKE CONCAT('%', #{q}, '%')
    OR quote LIKE CONCAT('%', #{q}, '%')
    OR tags LIKE CONCAT('%', #{q}, '%')
    )

 AND dynasty = #{dynasty} 
 AND genre = #{genre} 
 AND theme = #{theme} 
 AND season = #{season} 
 AND emotion = #{emotion} 
 AND scenery = #{scenery} 
 AND festival = #{festival} 
 AND historical_period = #{historicalPeriod} 
 AND poetic_form = #{poeticForm} 
 AND rhetorical_device = #{rhetoricalDevice} 
 AND famous_line_type = #{famousLineType} 
ORDER BY

    difficulty DESC, id ASC
    len DESC, id ASC
    RAND()
    id ASC

LIMIT #{size} OFFSET #{offset}

SELECT COUNT(1)
FROM poem
WHERE 1 = 1

    AND (
    title LIKE CONCAT('%', #{q}, '%')
    OR author LIKE CONCAT('%', #{q}, '%')
    OR quote LIKE CONCAT('%', #{q}, '%')
    OR tags LIKE CONCAT('%', #{q}, '%')
    )

 AND dynasty = #{dynasty} 
 AND genre = #{genre} 
 AND theme = #{theme} 
 AND season = #{season} 
 AND emotion = #{emotion} 
 AND scenery = #{scenery} 
 AND festival = #{festival} 
 AND historical_period = #{historicalPeriod} 
 AND poetic_form = #{poeticForm} 
 AND rhetorical_device = #{rhetoricalDevice} 
 AND famous_line_type = #{famousLineType}

SELECT id, title, author, dynasty, genre, theme, difficulty, hot, len, quote, content, translation, analysis, tags, cover_url, audio_url, audio_duration, audio_type, season, emotion, scenery, festival, historical_period, poetic_form, rhetorical_device, famous_line_type
FROM poem
WHERE id = #{id}

mapper.update:
UPDATE poem
SET audio_url = #{audioUrl},
    audio_duration = #{audioDuration},
    audio_type = #{audioType}
WHERE id = #{id}

UPDATE poem
SET cover_url = #{coverUrl}
WHERE id = #{id}

mapper.delete:
DELETE FROM poem_fav
WHERE user_id = #{userId}
  AND poem_id = #{poemId}

mapper.select:
SELECT COUNT(1)
FROM poem_fav
WHERE user_id = #{userId}
  AND poem_id = #{poemId}

SELECT p.id, p.title, p.author, p.dynasty, p.genre, p.theme, p.difficulty, p.hot, p.len, p.quote, p.translation, p.analysis, p.tags, p.cover_url, p.audio_url, p.audio_duration, p.audio_type, p.season, p.emotion, p.scenery, p.festival, p.historical_period, p.poetic_form, p.rhetorical_device, p.famous_line_type, 1 as fav
FROM poem p
         INNER JOIN poem_fav f ON p.id = f.poem_id
WHERE f.user_id = #{userId}
ORDER BY f.create_time DESC
    LIMIT #{size} OFFSET #{offset}

SELECT COUNT(1)
FROM poem_fav
WHERE user_id = #{userId}

SELECT poem_id
FROM poem_fav
WHERE user_id = #{userId}

    AND poem_id IN

        #{id}

SELECT author as `key`,
COUNT(*) as count,
SUBSTRING_INDEX(GROUP_CONCAT(DISTINCT dynasty ORDER BY dynasty), ',', 1) as dynastyTop,
SUBSTRING_INDEX(GROUP_CONCAT(DISTINCT genre ORDER BY genre), ',', 1) as genreTop,
SUBSTRING_INDEX(GROUP_CONCAT(quote ORDER BY hot DESC), ',', 1) as sampleQuote
FROM poem
WHERE author IS NOT NULL
AND author != ''
 AND dynasty = #{dynasty} 
 AND genre = #{genre} 
 AND theme = #{theme} 
 AND season = #{season} 
 AND emotion = #{emotion} 
 AND scenery = #{scenery} 
 AND festival = #{festival} 
 AND historical_period = #{historicalPeriod} 
 AND poetic_form = #{poeticForm} 
 AND rhetorical_device = #{rhetoricalDevice} 
GROUP BY author
ORDER BY count DESC, author

SELECT
author as `key`,
COUNT(*) as count,
MAX(dynasty) as dynastyTop,
MAX(genre) as genreTop,
MAX(CASE WHEN quote IS NOT NULL AND quote != '' THEN title END) as sampleTitle,
MAX(CASE WHEN quote IS NOT NULL AND quote != '' THEN quote END) as sampleQuote,
MAX(CASE WHEN content IS NOT NULL AND content != '' THEN content END) as sampleContent
FROM poem
WHERE 1 = 1
AND author IS NOT NULL AND author != ''

    AND dynasty = #{dynasty}


    AND genre = #{genre}


    AND theme = #{theme}


    AND season = #{season}


    AND emotion = #{emotion}


    AND scenery = #{scenery}


    AND festival = #{festival}


    AND historical_period = #{historicalPeriod}


    AND poetic_form = #{poeticForm}


    AND rhetorical_device = #{rhetoricalDevice}

GROUP BY author
ORDER BY COUNT(*) DESC, author ASC
